// 实现 Cloneable 并重写 clone
public class Resume implements Cloneable {
    private String name;
    private StringBuilder skills;        // 可变引用字段

    public Resume(String name) { this.name = name; this.skills = new StringBuilder(); }

    @Override
    public Resume clone() {
        try {
            Resume copy = (Resume) super.clone();      // 浅拷贝
            copy.skills = new StringBuilder(this.skills); // 手动深拷贝可变字段
            return copy;
        } catch (CloneNotSupportedException e) {
            throw new AssertionError(e);
        }
    }
}
// 用原型克隆出相似对象再微调，避免重复构造
